/**
 * Project the market tiers in capital/reference/europe_scope.json (the one
 * definition; capital's europe_scope.tier_of reads the same file) into
 * web/lib/mandate/agent/marketTiers.generated.ts. Turbopack's root is web/, so
 * the site cannot import the JSON itself.
 *
 * FREE. Run after changing a tier: npx tsx scripts/emit_market_tiers.ts
 * marketTiers.test.ts fails while the generated file is stale.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";

const scope = JSON.parse(readFileSync(resolve(__dirname, "..", "..", "capital", "reference", "europe_scope.json"), "utf8"));
const tiers: Record<string, string> = { EU: scope._meta.tiers.eu };
for (const c of scope.countries as { iso2: string; tier: string }[]) tiers[c.iso2] = c.tier;
const body = Object.keys(tiers).sort().map((k) => `  ${k}: "${tiers[k]}",`).join("\n");
const out = resolve(__dirname, "..", "lib", "mandate", "agent", "marketTiers.generated.ts");
writeFileSync(out, `// GENERATED by web/scripts/emit_market_tiers.ts from capital/reference/europe_scope.json. Do not edit.
export type MarketTier = "core" | "hub" | "out";
export const MARKET_TIER: Record<string, MarketTier> = {
${body}
};
`);
console.log(`wrote ${out}`);
